import re
lines=[l for l in open('grad.txt',encoding='utf-8').read().split('\n') if l]
out={}
for l in lines[1:-1]:
    # split hex panel content
    pos = l[1:9]
    seg = l[10:35]+l[36:61]
    # find color codes
    parts = re.findall(r'\x1b\[38;2;(\d+);(\d+);(\d+)m(..)', seg)
    for (r,g,b),h in parts:
        out[int(h,16)]=(int(r),int(g),int(b))
print(len(out))
for i in range(256):
    if i in out: print('%02x %s'%(i,out[i]))
    else: print('%02x MISSING'%i)
" 2>&1 | head -40"}

