//! Minimal local replacement for the `terminal_size` helper crate.
//!
//! Reports the size of the terminal attached to a standard stream by asking the
//! operating system for the window size of the associated tty.

use std::os::unix::io::AsRawFd;

/// Width of a terminal in columns.
#[derive(Copy, Clone, Debug, Default, Eq, PartialEq, Ord, PartialOrd, Hash)]
pub struct Width(pub u16);

/// Height of a terminal in rows.
#[derive(Copy, Clone, Debug, Default, Eq, PartialEq, Ord, PartialOrd, Hash)]
pub struct Height(pub u16);

#[derive(Copy, Clone, Debug, Default, Eq, PartialEq, Ord, PartialOrd, Hash)]
#[repr(C)]
struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn ioctl(fd: i32, request: u64, ...) -> i32;
}

const TIOCGWINSZ: u64 = 0x5413;

fn size_of(fd: i32) -> Option<(Width, Height)> {
    let mut winsize = Winsize::default();
    let rv = unsafe { ioctl(fd, TIOCGWINSZ, &mut winsize as *mut Winsize) };
    if rv != 0 {
        return None;
    }
    let rows = winsize.ws_row;
    let cols = winsize.ws_col;
    if rows > 0 && cols > 0 {
        Some((Width(cols), Height(rows)))
    } else {
        None
    }
}

/// Returns the size of the terminal attached to standard output.
pub fn terminal_size() -> Option<(Width, Height)> {
    size_of(std::io::stdout().as_raw_fd())
}
