pub fn build_command() -> Command {
    let file = Arg::new("file")
        .value_name("FILE")
        .help("The file to display. If no FILE argument is given, read from STDIN");

    let length = Arg::new("length")
        .short('n')
        .long("length")
        .visible_alias("bytes")
        .visible_short_alias('c')
        .alias("l")
        .value_name("N")
        .help(
