             would be identical to the preceding group of lines, are replaced with a line \
             comprised of a single asterisk",
        );

    let color = Arg::new("color")
        .long("color")
        .value_name("WHEN")
        .default_value("always")
        .value_parser(clap::builder::PossibleValuesParser::new([
            value_with_help("always", "Always use colorized output"),
            value_with_help(
                "auto",
                "Only displays colors if the output goes to an interactive terminal",
            ),
            value_with_help("never", "Do not use colorized output"),
            value_with_help("force", "Override the NO_COLOR environment variable"),
        ]))
        .help("When to use colors");

    let border = Arg::new("border")
        .long("border")
        .value_name("STYLE")
        .default_value("unicode")
        .value_parser(clap::builder::PossibleValuesParser::new([
