            value_with_help("ascii", "Draw a border with ASCII characters"),
            value_with_help("none", "Do not draw a border at all"),
        ]))
        .help("Whether to draw a border");

    let plain = Arg::new("plain")
        .short('p')
        .long("plain")
        .action(ArgAction::SetTrue)
        .help(
