            value_with_help("codepage-437", "Uses code page 437 (for non-ASCII bytes)"),
            value_with_help(
                "braille",
                "Uses braille characters for non-printable bytes",
            ),
        ]))
        .help("Defines how bytes are mapped to characters");

    let color_scheme = Arg::new("color-scheme")
        .long("color-scheme")
        .value_name("FORMAT")
        .default_value("default")
        .value_parser(clap::builder::PossibleValuesParser::new([
            value_with_help(
