                .map(|a| a.to_string())
                .unwrap_or_else(|| "...".to_owned());
            clap::Error::value_validation(arg, s.clone(), err.to_string().into())
        });
        match parsed {
            Ok(v) => Ok(v),
            Err(e) => Err(e.with_cmd(cmd)),
        }
    }
}

fn nonzero_usize_parser() -> NonZeroUsizeParser {
    NonZeroUsizeParser
}''')
