use clap::builder::{Arg, ArgAction, Command, PossibleValue, PossibleValuesParser, ValueParser};
use clap_complete::Shell;

pub const BIN_NAME: &str = "hexyl";
pub const VERSION: &str = "0.16.0";
pub const ABOUT: &str = "A command-line hex viewer";

/// Builds the command definition.
///
/// `for_help` selects the variant used only for rendering `--help`/`-h`.  In that
/// variant the aliases and default values are hidden from the automatically
/// generated "spec" annotations and are spelled out inside the help texts instead,
/// which is what the reference implementation displays.
pub fn build_command(for_help: bool) -> Command {
    macro_rules! text {
        ($base:expr, $short:expr, $long:expr) => {{
            if for_help {
                ($base, $base $short)
            } else {
                ($base, $base)
            }
        }};
    }

    // (help, long_help) pairs.  The `$short`/`$long` fragments carry the
    // annotations that clap would otherwise emit as spec values.
    let file_help = "The file to display. If no FILE argument is given, read from STDIN";
    let length_base = "Only read N bytes from the input. The N argument can also include a unit \
with a decimal prefix (kB, MB, ..) or binary prefix (kiB, MiB, ..), or can be specified using a \
hex number. The short option '-l' can be used as an alias.\nExamples: --length=64, \
--length=4KiB, --length=0xff";
    let length_spec_short = " [aliases: bytes] [short aliases: c]";
    let length_spec_long = "\n\n[aliases: bytes]\n[short aliases: c]";
    let skip_base = "Skip the first N bytes of the input. The N argument can also include a unit \
(see `--length` for details).\nA negative value is valid and will seek from the end of the file.";
    let block_base = "Sets the size of the `block` unit to SIZE.\nExamples: --block-size=1024, \
--block-size=4kB";
    let sque_base = "Displays all input data. Otherwise any number of groups of output lines \
which would be identical to the preceding group of lines, are replaced with a line comprised of \
a single asterisk";
    let color_base = "When to use colors";
    let border_base = "Whether to draw a border";
    let plain_base =
        "Display output with --no-characters, --no-position, --border=none, and --color=never";
    let nochar_base = "Do not show the character panel on the right";
    let char_base = "Show the character panel on the right. This is the default, unless \
--no-characters has been specified";
    let ctable_base = "Defines how bytes are mapped to characters";
    let cscheme_base = "Defines the color scheme for the characters";
    let nopos_base = "Whether to display the position panel on the left";
    let offset_base = "Add N bytes to the displayed file position. The N argument can also \
include a unit (see `--length` for details).\nA negative value is valid and calculates an \
offset relative to the end of the file.";
    let panels_base = "Sets the number of hex data panels to be displayed. `--panels=auto` will \
display the maximum number of hex data panels based on the current terminal width. By default, \
hexyl will show two panels, unless the terminal is not wide enough for that";
    let group_base = "Number of bytes/octets that should be grouped together. You can use the \
'--endianness' option to control the ordering of the bytes within a group. '--groupsize' can be \
used as an alias (xxd-compatibility)";
    let endian_base = "Whether to print out groups in little-endian or big-endian format. This \
option only has an effect if the '--group-size' is larger than 1. '-e' can be used as an alias \
for '--endianness=little'";
    let base_base =
        "Sets the base used for the bytes. The possible options are binary, octal, decimal, and \
hexadecimal";
    let twidth_base = "Sets the number of terminal columns to be displayed.\nSince the terminal \
width may not be an evenly divisible by the width per hex data column, this will use the \
greatest number of hex data panels that can fit in the requested width but still leave some \
space to the right.\nCannot be used with other width-setting options.";
    let colortbl_base = "Print a table showing how different types of bytes are colored";
    let include_base = "Output in C include file style";
    let compl_base = "Show shell completion for a certain shell";

    let file = Arg::new("file")
        .value_name("FILE")
        .help(file_help);

    let length = Arg::new("length")
        .short('n')
        .long("length")
        .visible_alias("bytes")
        .visible_short_alias('c')
        .alias("l")
        .value_name("N")
        .help(length_base);

    let skip = Arg::new("skip")
        .short('s')
        .long("skip")
        .value_name("N")
        .help(skip_base);

    let block_size = Arg::new("block-size")
        .long("block-size")
        .value_name("SIZE")
        .default_value("512")
        .help(block_base);

    let no_squeezing = Arg::new("no-squeezing")
        .short('v')
        .long("no-squeezing")
        .action(ArgAction::SetTrue)
        .help(sque_base);

    let color = Arg::new("color")
        .long("color")
        .value_name("WHEN")
        .default_value("always")
        .value_parser(PossibleValuesParser::new(color_values()))
        .help(color_base);

    let border = Arg::new("border")
        .long("border")
        .value_name("STYLE")
        .default_value("unicode")
        .value_parser(PossibleValuesParser::new(border_values()))
        .help(border_base);

    let plain = Arg::new("plain")
        .short('p')
        .long("plain")
        .action(ArgAction::SetTrue)
        .help(plain_base);

    let no_characters = Arg::new("no-characters")
        .long("no-characters")
        .action(ArgAction::SetTrue)
        .help(nochar_base);

    let characters = Arg::new("characters")
        .short('C')
        .long("characters")
        .action(ArgAction::SetTrue)
        .help(char_base);

    let character_table = Arg::new("character-table")
        .long("character-table")
        .value_name("FORMAT")
        .default_value("default")
        .value_parser(PossibleValuesParser::new(character_table_values()))
        .help(ctable_base);

    let color_scheme = Arg::new("color-scheme")
        .long("color-scheme")
        .value_name("FORMAT")
        .default_value("default")
        .value_parser(PossibleValuesParser::new(color_scheme_values()))
        .help(cscheme_base);

    let no_position = Arg::new("no-position")
        .short('P')
        .long("no-position")
        .action(ArgAction::SetTrue)
        .help(nopos_base);

    let endianness_alias = Arg::new("endianness-little")
        .short('e')
        .action(ArgAction::SetTrue)
        .hide(true)
        .help("An alias for '--endianness=little'");

    let display_offset = Arg::new("display-offset")
        .short('o')
        .long("display-offset")
        .value_name("N")
        .default_value("0")
        .help(offset_base);

    let panels = Arg::new("panels")
        .long("panels")
        .value_name("N")
        .conflicts_with("terminal-width")
        .help(panels_base);

    let group_size = Arg::new("group-size")
        .short('g')
        .long("group-size")
        .alias("groupsize")
        .value_name("N")
        .default_value("1")
        .value_parser(PossibleValuesParser::new(group_size_values()))
        .help(group_base);

    let endianness = Arg::new("endianness")
        .long("endianness")
        .value_name("FORMAT")
        .default_value("big")
        .value_parser(PossibleValuesParser::new(endianness_values()))
        .help(endian_base);

    let base = Arg::new("base")
        .short('b')
        .long("base")
        .value_name("B")
        .default_value("hexadecimal")
        .help(base_base);

    let terminal_width = Arg::new("terminal-width")
        .long("terminal-width")
        .value_name("N")
        .value_parser(ValueParser::new(parse_nonzero_usize))
        .help(twidth_base);

    let print_color_table = Arg::new("print-color-table")
        .long("print-color-table")
        .action(ArgAction::SetTrue)
        .help(colortbl_base);

    let include = Arg::new("include")
        .short('i')
        .long("include")
        .action(ArgAction::SetTrue)
        .help(include_base);

    let completion = Arg::new("completion")
        .long("completion")
        .value_name("SHELL")
        .value_parser(clap::builder::EnumValueParser::<Shell>::new())
        .help(compl_base);

    if !for_help {
        return Command::new(BIN_NAME)
            .version(VERSION)
            .about(ABOUT)
            .max_term_width(90)
            .args([
                file, length, skip, block_size, no_squeezing, color, border, plain, no_characters,
                characters, character_table, color_scheme, no_position, endianness_alias,
                display_offset, panels, group_size, endianness, base, terminal_width,
                print_color_table, include, completion,
            ]);
    }

    // Variant used exclusively for rendering the help screens.
    let length = length
        .alias("bytes")
        .short_alias('c')
        .help(format!("{length_base}{length_spec_short}"))
        .long_help(format!("{length_base}{length_spec_long}"));
    let block_size = Arg::new("block-size")
        .long("block-size")
        .value_name("SIZE")
        .default_value("512")
        .hide_default_value(true)
        .help(format!("{block_base} [default: 512]"))
        .long_help(format!("{block_base}\n\n[default: 512]"));
    let color = Arg::new("color")
        .long("color")
        .value_name("WHEN")
        .default_value("always")
        .hide_default_value(true)
        .value_parser(PossibleValuesParser::new(color_values()))
        .help(format!(
            "{color_base} [default: always] [possible values: always, auto, never, force]"
        ))
        .long_help(format!("{color_base}\n\n[default: always]"));
    let border = Arg::new("border")
        .long("border")
        .value_name("STYLE")
        .default_value("unicode")
        .hide_default_value(true)
        .value_parser(PossibleValuesParser::new(border_values()))
        .help(format!(
            "{border_base} [default: unicode] [possible values: unicode, ascii, none]"
        ))
        .long_help(format!("{border_base}\n\n[default: unicode]"));
    let character_table = Arg::new("character-table")
        .long("character-table")
        .value_name("FORMAT")
        .default_value("default")
        .hide_default_value(true)
        .value_parser(PossibleValuesParser::new(character_table_values()))
        .help(format!(
            "{ctable_base} [default: default] [possible values: default, ascii, \
codepage-1047, codepage-437, braille]"
