        .hide_default_value(true)
        .value_parser(PossibleValuesParser::new(color_scheme_values()))
        .help(format!(
            "{cscheme_base} [default: default] [possible values: default, gradient]"
        ))
        .long_help(format!("{cscheme_base}\n\n[default: default]"));
