fn pv(name: &'static str, help: &'static str) -> PossibleValue {
    PossibleValue::new(name).help(help)
}

pub fn color_values() -> [PossibleValue; 4] {
    [
        pv("always", "Always use colorized output"),
        pv(
            "auto",
            "Only displays colors if the output goes to an interactive terminal",
        ),
        pv("never", "Do not use colorized output"),
        pv("force", "Override the NO_COLOR environment variable"),
    ]
}

pub fn border_values() -> [PossibleValue; 3] {
    [
        pv("unicode", "Draw a border with Unicode characters"),
        pv("ascii", "Draw a border with ASCII characters"),
        pv("none", "Do not draw a border at all"),
    ]
}

pub fn character_table_values() -> [PossibleValue; 5] {
    [
        pv("default", "Show printable ASCII characters as-is, '⋄' for NULL bytes, ' ' for space, '_' for other ASCII whitespace, '•' for other ASCII characters, and '×' for non-ASCII bytes"),
        pv("ascii", "Show printable ASCII as-is, ' ' for space, '.' for everything else"),
        pv("codepage-1047", "Show printable EBCDIC as-is, ' ' for space, '.' for everything else"),
        pv("codepage-437", "Uses code page 437 (for non-ASCII bytes)"),
        pv("braille", "Uses braille characters for non-printable bytes"),
    ]
}

pub fn color_scheme_values() -> [PossibleValue; 2] {
    [
        pv("default", "Show the default colors: bright black for NULL bytes, green for ASCII space characters and non-printable ASCII, cyan for printable ASCII characters, and yellow for non-ASCII bytes"),
        pv("gradient", "Show bright black for NULL bytes, cyan for printable ASCII characters, a gradient from pink to violet for non-printable ASCII characters and a heatmap-like gradient from red to yellow to white for non-ASCII bytes"),
    ]
}

pub fn group_size_values() -> [PossibleValue; 4] {
    [
        pv("1", "Grouped together every byte/octet"),
        pv("2", "Grouped together every 2 bytes/octets"),
        pv("4", "Grouped together every 4 bytes/octets"),
        pv("8", "Grouped together every 8 bytes/octets"),
    ]
}

pub fn endianness_values() -> [PossibleValue; 2] {
    [
        pv("little", "Print out groups in little-endian format"),
        pv("big", "Print out groups in big-endian format"),
    ]
}

/// Parses a non-zero unsigned integer (`NonZeroUsize`).
fn parse_nonzero_usize(s: &str) -> Result<std::num::NonZeroUsize, String> {
    s.parse::<std::num::NonZeroUsize>()
        .map_err(|err| err.to_string())
}
