//! Parsing of byte counts such as `64`, `4KiB`, `0xff` or `2block`.

use anyhow::{anyhow, bail, Context, Result};

/// Multiplier of a unit suffix.  `block` uses the block size configured with
/// `--block-size`.
fn unit_multiplier(unit: &str, block_size: i64, allow_block: bool) -> Result<i64> {
    if unit.is_empty() {
        return Ok(1);
    }
    if !allow_block && unit.eq_ignore_ascii_case("block") {
        bail!("can not use 'block(s)' as a unit to specify block size");
    }
    let mult = match unit.to_ascii_lowercase().as_str() {
        "kb" => 1_000i64,
        "kib" => 1_024,
        "mb" => 1_000_000,
        "mib" => 1_048_576,
        "gb" => 1_000_000_000,
        "gib" => 1_073_741_824,
        "tb" => 1_000_000_000_000,
        "tib" => 1_099_511_627_776,
        "block" => block_size,
        _ => return Err(anyhow!("invalid unit \"{}\"", unit)),
    };
    Ok(mult)
}

fn parse_inner(
    s: &str,
    block_size: i64,
    allow_sign: bool,
    allow_block: bool,
    require_positive: bool,
) -> Result<i64> {
    if s.is_empty() {
        bail!("no character data found, did you forget to write it?");
    }
    let (sign, rest) = match s.as_bytes()[0] {
        b'+' if allow_sign => (1i64, &s[1..]),
        b'-' if allow_sign => (-1i64, &s[1..]),
        _ => (1i64, s),
