//! Color schemes for the byte categories and the file position.

use crate::tables::GRADIENT;

/// A terminal color.  `code` is the escape sequence used to switch to it.
#[derive(Clone, PartialEq, Eq, Debug)]
pub struct Color {
    pub code: String,
}

impl Color {
    pub fn ansi(code: u8) -> Self {
        Self {
            code: format!("\x1b[{}m", code),
        }
    }

    /// Truecolor without zero padding (used for `HEXYL_COLOR_*` values).
    pub fn rgb(r: u8, g: u8, b: u8) -> Self {
        Self {
            code: format!("\x1b[38;2;{r};{g};{b}m"),
        }
    }

    /// Truecolor with zero padding (used by the gradient scheme).
    pub fn rgb_padded(r: u8, g: u8, b: u8) -> Self {
        Self {
            code: format!("\x1b[38;2;{r:03};{g:03};{b:03}m"),
        }
    }
}

pub const RESET: &str = "\x1b[39m";

/// Named colors understood by the `HEXYL_COLOR_*` environment variables.
const NAMES: &[(&str, u8)] = &[
    ("black", 30),
    ("red", 31),
    ("green", 32),
    ("yellow", 33),
    ("blue", 34),
    ("magenta", 35),
    ("cyan", 36),
    ("white", 37),
    ("bright black", 90),
    ("bright red", 91),
    ("bright green", 92),
    ("bright yellow", 93),
    ("bright blue", 94),
    ("bright magenta", 95),
    ("bright cyan", 96),
    ("bright white", 97),
];

fn parse_color(v: &str) -> Option<Color> {
    if let Some((_, code)) = NAMES.iter().find(|(n, _)| *n == v) {
        return Some(Color::ansi(*code));
    }
    if v.len() == 7 && v.as_bytes()[0] == b'#' {
        let hex = |s: &str| u8::from_str_radix(s, 16).ok();
        if let (Some(r), Some(g), Some(b)) = (hex(&v[1..3]), hex(&v[3..5]), hex(&v[5..7])) {
            return Some(Color::rgb(r, g, b));
        }
    }
    None
}

fn env_color(name: &str) -> Option<Color> {
    std::env::var_os(name)
        .and_then(|v| v.into_string().ok())
        .and_then(|v| parse_color(&v))
}

/// How the characters panel is colored.
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Scheme {
    Default,
    Gradient,
}

/// All colors used while rendering.
pub struct Colors {
    /// Escape sequence per byte value.
    pub byte: Vec<Color>,
    pub offset: Color,
}

impl Colors {
    pub fn new(scheme: Scheme) -> Self {
        let offset = env_color("HEXYL_COLOR_OFFSET").unwrap_or_else(|| Color::ansi(90));
        match scheme {
            Scheme::Gradient => {
                let byte = GRADIENT
                    .iter()
                    .map(|(r, g, b)| Color::rgb_padded(*r, *g, *b))
                    .collect();
                Self { byte, offset }
            }
            Scheme::Default => {
                let null = env_color("HEXYL_COLOR_NULL").unwrap_or_else(|| Color::ansi(90));
                let whitespace = env_color("HEXYL_COLOR_ASCII_WHITESPACE")
                    .unwrap_or_else(|| Color::ansi(32));
                let printable = env_color("HEXYL_COLOR_ASCII_PRINTABLE")
                    .unwrap_or_else(|| Color::ansi(36));
                let other =
                    env_color("HEXYL_COLOR_ASCII_OTHER").unwrap_or_else(|| Color::ansi(32));
                let nonascii =
                    env_color("HEXYL_COLOR_NONASCII").unwrap_or_else(|| Color::ansi(33));
                let mut byte = Vec::with_capacity(256);
                for b in 0u8..=255 {
                    let c = if b == 0 {
                        &null
                    } else if b.is_ascii_whitespace() {
                        &whitespace
                    } else if (0x20..=0x7e).contains(&b) {
                        &printable
                    } else if b < 0x80 {
                        &other
                    } else {
                        &nonascii
                    };
                    byte.push(c.clone());
                }
                Self { byte, offset }
            }
        }
    }

    pub fn for_byte(&self, b: u8) -> &Color {
        &self.byte[b as usize]
    }
}
RUSTEOF
echo ok"}

