//! Rendering of the hexyl output: borders, position panel, hex data panels and
//! the character panel.

use std::io::Write;

use crate::color::{Color, Colors, RESET};
use crate::tables;

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Border {
    Unicode,
    Ascii,
    None,
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Base {
    Hex,
    Octal,
    Decimal,
    Binary,
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Endianness {
    Little,
    Big,
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum CharTable {
    Default,
    Ascii,
    Codepage1047,
    Codepage437,
    Braille,
}

impl CharTable {
    pub fn character(&self, b: u8) -> char {
        match self {
            CharTable::Default => tables::DEFAULT_CHARS[b as usize],
            CharTable::Ascii => tables::ASCII_CHARS[b as usize],
            CharTable::Codepage1047 => tables::CP1047_CHARS[b as usize],
            CharTable::Codepage437 => tables::CP437_CHARS[b as usize],
            CharTable::Braille => tables::BRAILLE_CHARS[b as usize],
        }
    }
}

/// Number of characters a single byte occupies in the hex panel.
pub fn unit_width(base: Base) -> usize {
    match base {
        Base::Hex => 2,
        Base::Octal | Base::Decimal => 3,
        Base::Binary => 8,
    }
}

pub fn format_byte(base: Base, b: u8) -> String {
    match base {
        Base::Hex => format!("{b:02x}"),
        Base::Octal => format!("{b:03o}"),
        Base::Decimal => format!("{b:03}"),
        Base::Binary => format!("{b:08b}"),
    }
}

pub struct Layout {
    pub panels: usize,
    pub bytes_per_panel: usize,
    pub group_size: usize,
    pub base: Base,
    pub endianness: Endianness,
    pub show_position: bool,
    pub show_characters: bool,
    pub border: Border,
}

impl Layout {
    pub fn unit_width(&self) -> usize {
        unit_width(self.base)
    }

    /// Width of the hex data of a full panel (without the leading and trailing
    /// padding spaces).
    pub fn hex_data_width(&self) -> usize {
        8 * self.unit_width() + (self.bytes_per_panel / self.group_size) - 1
    }

    /// Total width of a rendered line.
    pub fn total_width(&self) -> usize {
        let hw = self.hex_data_width() + 2;
        let pos = if self.show_position { 9 } else { 0 };
        let chars = if self.show_characters {
            self.panels * 9
        } else {
            0
        };
        1 + pos + self.panels * hw + (self.panels - 1) + chars + 1
    }

    /// Widest line needed to fit `n` panels (used to determine the panel count).
    pub fn width_needed(&self, panels: usize, chars: usize) -> usize {
        let hw = self.hex_data_width() + 2;
        let pos = if self.show_position { 9 } else { 0 };
        1 + pos + panels * hw + (panels - 1) + chars
    }

    pub fn bytes_per_row(&self) -> usize {
        self.panels * self.bytes_per_panel
    }
}

pub struct BorderChars {
    pub left: char,
    pub right: char,
    pub solid: char,
    pub dashed: char,
    pub horizontal: char,
    pub top_left: char,
    pub top_right: char,
    pub bottom_left: char,
    pub bottom_right: char,
    pub enabled: bool,
}

impl BorderChars {
    pub fn new(border: Border) -> Self {
        match border {
            Border::Unicode => Self {
                left: '│',
                right: '│',
                solid: '│',
                dashed: '┊',
                horizontal: '─',
                top_left: '┌',
                top_right: '┐',
                bottom_left: '└',
                bottom_right: '┘',
                enabled: true,
            },
            Border::Ascii => Self {
                left: '|',
                right: '|',
                solid: '|',
                dashed: '|',
                horizontal: '-',
                top_left: '+',
                top_right: '+',
                bottom_left: '+',
                bottom_right: '+',
                enabled: true,
            },
            Border::None => Self {
                left: ' ',
                right: ' ',
                solid: ' ',
                dashed: ' ',
                horizontal: ' ',
                top_left: ' ',
                top_right: ' ',
                bottom_left: ' ',
                bottom_right: ' ',
                enabled: false,
            },
        }
    }
}

fn panel_separator(bc: &BorderChars, first_of_kind: bool) -> char {
    if first_of_kind {
        bc.solid
    } else {
        bc.dashed
    }
}

/// Renders the top (or bottom) border line.  Returns `None` when no border is
/// drawn at all.
pub fn border_line(l: &Layout, bc: &BorderChars, top: bool) -> Option<String> {
    if !bc.enabled {
        return None;
    }
    let mut s = String::with_capacity(l.total_width() * 3);
    s.push(if top { bc.top_left } else { bc.bottom_left });
    if l.show_position {
        for _ in 0..8 {
            s.push(bc.horizontal);
        }
        s.push(if top { bc.solid } else { bc.solid });
        // The horizontal separator between panels uses the tee characters.
        s.pop();
        s.push(if top { '┬' } else { '┴' });
    }
    for i in 0..l.panels {
        for _ in 0..(l.hex_data_width() + 2) {
            s.push(bc.horizontal);
        }
        if i + 1 < l.panels || l.show_characters {
            s.push(if top { tee_top() } else { tee_bottom() });
        }
    }
    if l.show_characters {
        for i in 0..l.panels {
            for _ in 0..8 {
                s.push(bc.horizontal);
            }
            if i + 1 < l.panels {
                s.push(if top { tee_top() } else { tee_bottom() });
            }
        }
    }
    s.push(if top { bc.top_right } else { bc.bottom_right });
    Some(s)
}

fn tee_top() -> char {
    '┬'
}

fn tee_bottom() -> char {
    '┴'
}

/// Writer with color run tracking.
struct Out {
    s: String,
    colored: bool,
    cur: Option<usize>,
    colors: Vec<Color>,
}

impl Out {
    fn new(colored: bool, colors: Vec<Color>) -> Self {
        Self {
            s: String::new(),
            colored,
            cur: None,
            colors,
        }
    }

    fn push(&mut self, c: char) {
        self.s.push(c);
    }

    fn push_str(&mut self, s: &str) {
        self.s.push_str(s);
    }

    fn spaces(&mut self, n: usize) {
        for _ in 0..n {
            self.s.push(' ');
        }
    }

    fn start(&mut self, idx: usize) {
        if !self.colored {
            return;
        }
        if self.cur != Some(idx) {
            self.s.push_str(&self.colors[idx].code);
            self.cur = Some(idx);
        }
    }

    fn reset(&mut self) {
        if self.colored {
            self.s.push_str(RESET);
        }
        self.cur = None;
    }
}

/// Index of a color inside the writer's color table.
fn color_index(colors: &Colors, c: &Color) -> usize {
    // Colors are stored in a fixed order: the byte table first, the offset
    // color last.
    colors.byte.len()
}

fn offset_index(colors: &Colors) -> usize {
    colors.byte.len()
}

fn byte_index(colors: &Colors, b: u8) -> usize {
    b as usize
}

fn build_color_vec(colors: &Colors) -> Vec<Color> {
    let mut v = colors.byte.clone();
    v.push(colors.offset.clone());
    v
}

/// Renders one data row.
///
/// When `squeeze` is set an asterisk marker is drawn in the position area and
/// all panels are left empty.
pub fn render_row(
    l: &Layout,
    colors: &Colors,
    ct: &CharTable,
    pos_str: &str,
    data: &[u8],
    squeeze: bool,
    colored: bool,
) -> String {
    let bc = BorderChars::new(l.border);
    let mut out = Out::new(colored, build_color_vec(colors));

    out.push(bc.left);
    out.start(offset_index(colors));
    if l.show_position {
        out.push_str(pos_str);
        out.reset();
        if pos_str.len() < 8 {
            out.spaces(8 - pos_str.len());
        }
    }

    let hex_data_width = l.hex_data_width();
    for p in 0..l.panels {
        if p > 0 || l.show_position {
            out.push(panel_separator(&bc, p == 0));
        }
        if squeeze && p == 0 && !l.show_position {
            out.start(offset_index(colors));
            out.push('*');
            out.reset();
        } else {
            out.push(' ');
        }
        let start = p * l.bytes_per_panel;
        let end = start + l.bytes_per_panel;
        let panel: &[u8] = if start < data.len() {
            &data[start..end.min(data.len())]
        } else {
            &[]
        };
        let mut written = 0usize;
        if !panel.is_empty() {
            let n_groups = panel.len().div_ceil(l.group_size);
            for (gi, chunk) in panel.chunks(l.group_size).enumerate() {
                let order: Vec<u8> = if l.endianness == Endianness::Little && l.group_size > 1 {
                    chunk.iter().rev().copied().collect()
                } else {
                    chunk.to_vec()
                };
                for b in order {
                    out.start(byte_index(colors, b));
                    let t = format_byte(l.base, b);
                    written += t.len();
                    out.push_str(&t);
                }
                if gi + 1 < n_groups {
                    out.push(' ');
                    written += 1;
                }
            }
        }
        if written < hex_data_width {
            out.spaces(hex_data_width - written);
        }
        out.reset();
        out.push(' ');
    }

    if l.show_characters {
        for p in 0..l.panels {
            out.push(panel_separator(&bc, p == 0));
            let start = p * l.bytes_per_panel;
            let end = start + l.bytes_per_panel;
            let panel: &[u8] = if start < data.len() {
                &data[start..end.min(data.len())]
            } else {
                &[]
            };
            for &b in panel {
                out.start(byte_index(colors, b));
                out.push(ct.character(b));
            }
            if panel.len() < l.bytes_per_panel {
                out.spaces(l.bytes_per_panel - panel.len());
            }
            out.reset();
        }
    }

    out.push(bc.right);
    out.s
}

/// Renders the "No content" row which is shown for empty input.
pub fn render_no_content(l: &Layout) -> String {
    // This row always uses the Unicode border characters, even with
    // `--border=ascii` or `--border=none`.
    let bc = BorderChars::new(Border::Unicode);
    let mut s = String::with_capacity(l.total_width() * 3);
    s.push(bc.left);
    if l.show_position {
        for _ in 0..8 {
            s.push(' ');
        }
        s.push(bc.solid);
    }
    for p in 0..l.panels {
        if p > 0 || l.show_position {
            s.push(panel_separator(&bc, p == 0));
        }
        s.push(' ');
        if p == 0 {
            s.push_str("No content");
        }
        let used = if p == 0 { 10 } else { 0 };
        s.push_str(&" ".repeat(l.hex_data_width().saturating_sub(used)));
        s.push(' ');
    }
    if l.show_characters {
        for p in 0..l.panels {
            s.push(panel_separator(&bc, p == 0));
            for _ in 0..l.bytes_per_panel {
                s.push(' ');
            }
        }
    }
    s.push(bc.right);
    s
}

/// Output helper that flushes lines to stdout.
pub struct Printer {
    colored: bool,
}

impl Printer {
    pub fn new(colored: bool) -> Self {
        Self { colored }
    }

    pub fn line(&self, s: &str) {
        let stdout = std::io::stdout();
        let mut lock = stdout.lock();
        let _ = lock.write_all(s.as_bytes());
        let _ = lock.write_all(b"\n");
    }

    pub fn raw(&self, s: &str) {
        let stdout = std::io::stdout();
        let mut lock = stdout.lock();
        let _ = lock.write_all(s.as_bytes());
    }
}

/// Formats the position of a row as a hexadecimal number, padded to at least
/// eight characters.
pub fn position_string(pos: u64) -> String {
    let s = format!("{pos:x}");
    if s.len() < 8 {
        format!("{pos:08x}")
    } else {
        s
    }
}
RUSTEOF
