//! hexyl - a command-line hex viewer.

mod byte_count;
mod cli;
mod color;
mod render;
mod tables;

use std::ffi::OsString;
use std::io::Read;
use std::num::NonZeroUsize;

use anyhow::{anyhow, bail, Context, Result};
use clap::error::ErrorKind;
use clap_complete::Shell;

use crate::byte_count as bc;
use crate::color::{Colors, Scheme};
use crate::render::{
    border_line, position_string, render_no_content, render_row, Base, Border, BorderChars,
    CharTable, Endianness, Layout, Printer,
};

/// Options collected from the command line.
struct Args {
    file: Option<OsString>,
    length: Option<i64>,
    skip: Option<i64>,
    block_size: i64,
    no_squeezing: bool,
    color: crate::color::Scheme,
    color_when: ColorWhen,
    border: Border,
    plain: bool,
    show_characters: bool,
    char_table: CharTable,
    no_position: bool,
    display_offset: i64,
    panels: Option<NonZeroUsize>,
    group_size: usize,
    endianness: Endianness,
    base: Base,
    terminal_width: Option<usize>,
    print_color_table: bool,
    include: bool,
    completion: Option<Shell>,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum ColorWhen {
    Always,
    Auto,
    Never,
    Force,
}

fn parse_base(s: &str) -> Result<Base> {
    let base = match s {
        "2" | "b" => Base::Binary,
        "8" | "o" => Base::Octal,
        "10" | "d" => Base::Decimal,
        "16" | "x" => Base::Hex,
        "binary" | "octal" | "decimal" | "hexadecimal" => {
            bail!("The number provided is not a valid base. Valid bases are 2, 8, 10, and 16.")
        }
        _ => bail!("The base provided is not valid. Valid bases are \"b\", \"o\", \"d\", and \"x\"."),
    };
    Ok(base)
}

fn parse_number_base(s: &str) -> Option<usize> {
    s.parse::<usize>().ok()
}

fn main() {
    let mut cmd = cli::build_command(false);
    let args: Vec<OsString> = std::env::args_os().collect();
    let matches = match cmd.clone().try_get_matches_from_mut(args.clone()) {
        Ok(m) => m,
        Err(err) => match err.kind() {
            ErrorKind::DisplayHelp => {
                let use_long = scan_help(&args);
                let mut c = cli::build_command(true);
                let text = if use_long {
                    c.render_long_help().to_string()
                } else {
                    c.render_help().to_string()
                };
                crate::color::print_styled(&text);
                std::process::exit(0);
            }
            ErrorKind::DisplayVersion => {
                println!("{} {}", cli::BIN_NAME, cli::VERSION);
                std::process::exit(0);
            }
            _ => {
                let _ = err.print();
                std::process::exit(err.exit_code());
            }
        },
    };

    let args = match collect_args(&matches) {
        Ok(a) => a,
        Err(e) => {
            print_error(&e);
            std::process::exit(1);
        }
    };

    if args.print_color_table {
        print_color_table();
        return;
    }

    if let Some(shell) = args.completion {
        let mut cmd = cli::build_command(false);
        let _ = clap_complete::generate(shell, &mut cmd, cli::BIN_NAME, &mut std::io::stdout());
        return;
    }

    if let Err(e) = run(&args) {
        print_error(&e);
        std::process::exit(1);
    }
}

/// Scans the command line for the first occurrence of a help flag in order to
/// know whether the long or the short help screen was requested.
fn scan_help(args: &[OsString]) -> bool {
    let value_taking = [
        "length",
        "bytes",
        "skip",
        "block-size",
        "color",
        "border",
        "character-table",
        "color-scheme",
        "display-offset",
        "panels",
        "group-size",
        "groupsize",
        "endianness",
        "base",
        "terminal-width",
        "completion",
    ];
    let mut i = 0;
    while i < args.len() {
        let a = args[i].to_string_lossy().to_string();
        if a == "--" {
            return false;
        }
        if a == "--help" {
            return true;
        }
        if a == "-h" {
            return false;
        }
        if let Some(rest) = a.strip_prefix("--") {
            let name = rest.split('=').next().unwrap_or("");
            if value_taking.contains(&name) && !rest.contains('=') {
                i += 1;
            }
        } else if a.len() > 1 && a.starts_with('-') {
            // Short options; the last one may consume the next argument.
            let chars: Vec<char> = a[1..].chars().collect();
            let value_shorts = ['n', 's', 'o', 'g', 'b', 'c', 'l'];
            let mut consumed_next = false;
            for (k, ch) in chars.iter().enumerate() {
                if *ch == 'h' {
                    return false;
                }
                if value_shorts.contains(ch) {
                    if k + 1 < chars.len() {
                        consumed_next = false;
                    } else {
                        consumed_next = true;
                    }
                    break;
                }
            }
            if consumed_next {
                i += 1;
            }
        }
        i += 1;
    }
    false
}

fn print_error(e: &anyhow::Error) {
    eprintln!("Error: {e:?}");
}

fn collect_args(m: &clap::ArgMatches) -> Result<Args> {
    let file = m.get_one::<String>("file").map(|s| OsString::from(s));
    let block_size_raw = m.get_one::<String>("block-size").unwrap().clone();
    let no_squeezing = m.get_flag("no-squeezing");
    let plain = m.get_flag("plain");
    let no_characters = m.get_flag("no-characters");
    let characters = m.get_flag("characters");
    let no_position = m.get_flag("no-position");
    let color = match m.get_one::<String>("color").unwrap().as_str() {
        "always" => ColorWhen::Always,
        "auto" => ColorWhen::Auto,
        "never" => ColorWhen::Never,
        _ => ColorWhen::Force,
    };
    let border = match m.get_one::<String>("border").unwrap().as_str() {
        "unicode" => Border::Unicode,
        "ascii" => Border::Ascii,
        _ => Border::None,
    };
    let char_table = match m.get_one::<String>("character-table").unwrap().as_str() {
        "default" => CharTable::Default,
        "ascii" => CharTable::Ascii,
        "codepage-1047" => CharTable::Codepage1047,
        "codepage-437" => CharTable::Codepage437,
        _ => CharTable::Braille,
    };
    let scheme = match m.get_one::<String>("color-scheme").unwrap().as_str() {
        "gradient" => Scheme::Gradient,
        _ => Scheme::Default,
    };
    let display_offset_raw = m.get_one::<String>("display-offset").unwrap().clone();
    let panels = m.get_one::<String>("panels").map(|s| s.clone());
    let group_size = m
        .get_one::<String>("group-size")
        .unwrap()
        .parse::<usize>()
        .unwrap();
    let endianness = if m.get_flag("endianness-little") {
        Endianness::Little
    } else {
        match m.get_one::<String>("endianness").unwrap().as_str() {
            "little" => Endianness::Little,
            _ => Endianness::Big,
        }
    };
    let base_raw = m.get_one::<String>("base").unwrap().clone();
    let terminal_width = m
        .get_one::<std::num::NonZeroUsize>("terminal-width")
        .map(|v| v.get());
    let length_raw = m.get_one::<String>("length").map(|s| s.clone());
    let skip_raw = m.get_one::<String>("skip").map(|s| s.clone());
    let print_color_table = m.get_flag("print-color-table");
    let include = m.get_flag("include");
    let completion = m.get_one::<Shell>("completion").copied();

    // Validation happens in a specific order: file, block size, skip, length,
    // display offset, base, panels.
    let _ = file.as_ref();

    let block_size = bc::parse_block_size(&block_size_raw).map_err(|e| {
        anyhow!(
            "{}{}",
            e,
            if let Some(src) = e.downcast_ref::<&str>() {
                "".to_string()
            } else {
                String::new()
            }
        )
    })?;

    let skip = match &skip_raw {
        Some(s) => Some(bc::parse_skip(s, block_size)?),
        None => None,
    };
    let length = match &length_raw {
        Some(s) => Some(bc::parse_count(s, block_size, "length")?),
        None => None,
    };
    let display_offset = bc::parse_count(&display_offset_raw, block_size, "display-offset")?;
    let base = parse_base(&base_raw)?;
    let panels = match &panels {
        Some(s) => Some(s.parse::<NonZeroUsize>().map_err(|e| {
            anyhow!("{}").context(format!(
                "failed to parse `--panels` arg \"{s}\" as unsigned nonzero integer"
            ))
        })?),
        None => None,
    };

    let show_characters = if no_characters {
        characters
    } else {
        !characters || true
    };

    Ok(Args {
        file,
        length,
        skip,
        block_size,
        no_squeezing,
        color: scheme,
        color_when: color,
        border,
        plain,
        show_characters: show_characters && !no_characters,
        char_table,
        no_position,
        display_offset,
        panels,
        group_size,
        endianness,
        base,
        terminal_width,
        print_color_table,
        include,
        completion,
    })
}

fn run(args: &Args) -> Result<()> {
    Ok(())
}

fn print_color_table() {}
