    completion: Option<Shell>,
}

fn main() {
    let argv: Vec<OsString> = std::env::args_os().collect();
    let mut cmd = cli::build_command(false);
    let matches = match cmd.clone().try_get_matches_from_mut(argv.clone()) {
        Ok(m) => m,
        Err(err) => match err.kind() {
            ErrorKind::DisplayHelp => {
                let use_long = scan_help(&argv);
                let mut c = cli::build_command(true);
                let text = if use_long {
                    c.render_long_help().to_string()
                } else {
