/// Finds the first help flag on the command line to decide between the long
/// and the short help screen.
fn scan_help(argv: &[OsString]) -> bool {
    let value_taking = [
        "length",
        "bytes",
        "skip",
        "block-size",
        "color",
        "border",
        "character-table",
        "color-scheme",
        "display-offset",
        "panels",
        "group-size",
        "groupsize",
        "endianness",
        "base",
        "terminal-width",
        "completion",
    ];
    let short_values = ['n', 's', 'o', 'g', 'b', 'c', 'l'];
    for (i, raw) in argv.iter().enumerate() {
        let a = raw.to_string_lossy().to_string();
        if a == "--" {
            return false;
        }
        if a == "--help" {
            return true;
        }
        if a == "-h" {
            return false;
        }
        if let Some(rest) = a.strip_prefix("--") {
            let name = rest.split('=').next().unwrap_or("");
            if value_taking.contains(&name) && !rest.contains('=') {
                return argv.get(i + 1).is_none();
            }
        } else if a.len() > 1 && a.starts_with('-') {
            let chars: Vec<char> = a[1..].chars().collect();
            for (k, ch) in chars.iter().enumerate() {
                if *ch == 'h' {
                    return false;
                }
                if short_values.contains(ch) {
                    if k + 1 < chars.len() {
                        return false;
                    }
                    return argv.get(i + 1).is_none();
                }
            }
        }
    }
    false
}

fn last_index_of(m: &clap::ArgMatches, name: &str) -> Option<usize> {
    m.indices_of(name).and_then(|mut it| it.next_back().map(|i| i.get()))
}

fn first_index_of(m: &clap::ArgMatches, name: &str) -> Option<usize> {
    m.indices_of(name).and_then(|mut it| it.next().map(|i| i.get()))
}

fn parse_base(s: &str) -> Result<Base> {
    match s {
        "2" | "b" => Ok(Base::Binary),
        "8" | "o" => Ok(Base::Octal),
        "10" | "d" => Ok(Base::Decimal),
        "16" | "x" => Ok(Base::Hex),
        "binary" | "octal" | "decimal" | "hexadecimal" => Err(anyhow!(
            "The number provided is not a valid base. Valid bases are 2, 8, 10, and 16."
        )),
        _ => Err(anyhow!(
            "The base provided is not valid. Valid bases are \"b\", \"o\", \"d\", and \"x\"."
        )),
    }
}

fn collect_args(m: &clap::ArgMatches) -> Result<Args> {
    let file = m.get_one::<String>("file").cloned();
    let block_size_raw = m.get_one::<String>("block-size").unwrap().clone();
    let no_squeezing = m.get_flag("no-squeezing");
    let plain = m.get_flag("plain");
    let no_position = m.get_flag("no-position");
    let color_when = match m.get_one::<String>("color").unwrap().as_str() {
        "always" => ColorWhen::Always,
        "auto" => ColorWhen::Auto,
        "never" => ColorWhen::Never,
        _ => ColorWhen::Force,
    };
    let border_raw = m.get_one::<String>("border").unwrap().clone();
    let char_table = match m.get_one::<String>("character-table").unwrap().as_str() {
        "default" => CharTable::Default,
        "ascii" => CharTable::Ascii,
        "codepage-1047" => CharTable::Codepage1047,
        "codepage-437" => CharTable::Codepage437,
        _ => CharTable::Braille,
    };
    let scheme = match m.get_one::<String>("color-scheme").unwrap().as_str() {
        "gradient" => Scheme::Gradient,
        _ => Scheme::Default,
    };
    let display_offset_raw = m.get_one::<String>("display-offset").unwrap().clone();
    let panels_raw = m.get_one::<String>("panels").cloned();
    let group_size = m
        .get_one::<String>("group-size")
        .unwrap()
        .parse::<usize>()
        .unwrap();
    let endianness = if m.get_flag("endianness-little") {
        Endianness::Little
    } else {
        match m.get_one::<String>("endianness").unwrap().as_str() {
            "little" => Endianness::Little,
            _ => Endianness::Big,
        }
    };
    let base_raw = m.get_one::<String>("base").unwrap().clone();
    let terminal_width = m
        .get_one::<NonZeroUsize>("terminal-width")
        .map(|v| v.get());
    let length_raw = m.get_one::<String>("length").cloned();
    let skip_raw = m.get_one::<String>("skip").cloned();
    let print_color_table = m.get_flag("print-color-table");
    let include = m.get_flag("include");
    let completion = m.get_one::<Shell>("completion").copied();

    // Opening the file first ensures that I/O errors are reported before
    // argument validation errors.
    if let Some(f) = &file {
        let meta = std::fs::metadata(f)
            .with_context(|| format!(""))?;
        if meta.is_dir() {
            bail!("'{f}' is a directory.");
        }
    }

    let block_size = bc::parse_block_size(&block_size_raw)?;
    let skip = match &skip_raw {
        Some(s) => Some(bc::parse_skip(s, block_size)?),
        None => None,
    };
    let length = match &length_raw {
        Some(s) => Some(bc::parse_count(s, block_size, "length")?),
        None => None,
    };
    let display_offset = bc::parse_count(&display_offset_raw, block_size, "display-offset")?;
    let base = parse_base(&base_raw)?;
    let panels = match &panels_raw {
        Some(s) => Some(
            s.parse::<NonZeroUsize>().map_err(|e| anyhow!("{e}")).with_context(|| {
                format!("failed to parse `--panels` arg \"{s}\" as unsigned nonzero integer")
            })?,
        ),
        None => None,
    };

    let show_characters = if plain {
        false
    } else {
        match (
            last_index_of(m, "characters"),
            last_index_of(m, "no-characters"),
        ) {
            (Some(c), Some(n)) => c > n,
            (Some(_), None) => true,
            (None, Some(_)) => false,
            (None, None) => true,
        }
    };
    let show_position = !no_position && !plain;

    let border = if m.indices_of("border").is_some() {
        match border_raw.as_str() {
            "unicode" => Border::Unicode,
            "ascii" => Border::Ascii,
            _ => Border::None,
        }
    } else if plain {
        Border::None
    } else {
        Border::Unicode
    };

    let color_when = if m.indices_of("color").is_some() {
        color_when
    } else if plain {
        ColorWhen::Never
    } else {
        ColorWhen::Always
    };

    Ok(Args {
        file,
        length,
        skip,
        block_size,
        no_squeezing,
        scheme,
        color_when,
        border,
        show_position,
        show_characters,
        char_table,
        display_offset,
        panels: panels.map(|p| p.get()),
        group_size,
        endianness,
        base,
        terminal_width,
        print_color_table,
        include,
        completion,
    })
}

/// Width of the terminal attached to standard output, if any.
fn terminal_width() -> Option<usize> {
    use std::os::unix::io::AsRawFd;
    extern "C" {
        fn ioctl(fd: i32, request: u64, ...) -> i32;
    }
    #[repr(C)]
    #[derive(Default)]
    struct Winsize {
        ws_row: u16,
        ws_col: u16,
        ws_xpixel: u16,
        ws_ypixel: u16,
    }
    let mut ws = Winsize::default();
    let rv = unsafe { ioctl(std::io::stdout().as_raw_fd(), 0x5413, &mut ws as *mut Winsize) };
    if rv == 0 && ws.ws_row > 0 && ws.ws_col > 0 {
        Some(ws.ws_col as usize)
    } else {
        None
    }
}

fn run(args: &Args) -> Result<()> {
    let colored = match args.color_when {
        ColorWhen::Always => std::env::var_os("NO_COLOR").is_none(),
        ColorWhen::Auto => {
            terminal_width().is_some() && std::env::var_os("NO_COLOR").is_none()
        }
        ColorWhen::Never => false,
        ColorWhen::Force => true,
    };

    let layout = determine_layout(args);
    let colors = Colors::new(args.scheme);
    let printer = Printer::new(colored);

    if args.include {
        return print_include(args);
    }

    if let Some(b) = border_line(&layout, &render::BorderChars::new(args.border), true) {
        printer.line(&b);
    }

    let (start, reader) = open_input(args)?;
    let mut reader = reader;
    let bytes_per_row = layout.bytes_per_row();
    let mut pos = start;
    let mut prev: Option<Vec<u8>> = None;
    let mut star_printed = false;
    loop {
        let mut buf = vec![0u8; bytes_per_row];
        let n = read_full(&mut reader, &mut buf)?;
        buf.truncate(n);
        if buf.is_empty() {
            if star_printed {
                let row = if layout.show_position {
                    render_row(
                        &layout,
                        &colors,
                        &args.char_table,
                        &position_string(pos),
                        &[],
                        false,
                        colored,
                    )
                } else {
                    render_row(
                        &layout,
                        &colors,
                        &args.char_table,
                        "*",
                        &[],
                        true,
                        colored,
                    )
                };
                printer.line(&row);
            }
            break;
        }
        let same = args.no_squeezing == false && prev.as_deref() == Some(buf.as_slice());
        if same {
            if !star_printed {
                let row = render_row(
                    &layout,
                    &colors,
                    &args.char_table,
                    "*",
                    &[],
                    true,
                    colored,
                );
                printer.line(&row);
                star_printed = true;
            }
        } else {
            let row = render_row(
                &layout,
                &colors,
                &args.char_table,
                &position_string(pos),
                &buf,
                false,
                colored,
            );
            printer.line(&row);
            prev = Some(buf);
            star_printed = false;
        }
        pos += n as u64;
    }

    if let Some(b) = border_line(&layout, &render::BorderChars::new(args.border), false) {
        printer.line(&b);
    }
    Ok(())
}

fn read_full(reader: &mut dyn Read, buf: &mut [u8]) -> Result<usize> {
    let mut n = 0;
    while n < buf.len() {
        match reader.read(&mut buf[n..]) {
            Ok(0) => break,
            Ok(k) => n += k,
            Err(e) if e.kind() == std::io::ErrorKind::Interrupted => {}
            Err(e) => return Err(anyhow!("{e}")),
        }
    }
    Ok(n)
}

fn determine_layout(args: &Args) -> Layout {
    let show_position = args.show_position;
    let show_characters = args.show_characters;
    let l0 = Layout {
        panels: 1,
        bytes_per_panel: 8,
        group_size: args.group_size,
        base: args.base,
        endianness: args.endianness,
        show_position,
        show_characters,
        border: args.border,
    };
    let hw = l0.hex_data_width() + 2;
    let pos_overhead = if show_position { 9 } else { 0 };
    let chars_cost = if show_characters { 8 } else { 0 };
    let per_panel = hw + chars_cost;
    let panels = match args.panels {
        Some(n) => n,
        None => {
            let w = args
                .terminal_width
                .or_else(|| terminal_width())
                .unwrap_or(80);
            let mut n = 1usize;
            while per_panel > 0 && w >= pos_overhead + 1 + (n + 1) * per_panel {
                n += 1;
            }
            n
        }
    };
    Layout {
        panels,
        bytes_per_panel: 8,
        group_size: args.group_size,
        base: args.base,
        endianness: args.endianness,
        show_position,
        show_characters,
        border: args.border,
    }
}

enum Input {
    File(std::fs::File),
    Stdin(std::io::Stdin),
}

fn open_input(args: &Args) -> Result<(u64, Box<dyn Read>)> {
    let mut start = 0u64;
    let reader: Box<dyn Read> = match &args.file {
        Some(f) => {
            let file = std::fs::File::open(f).map_err(|e| anyhow!("{e}"))?;
            let mut file = file;
            if let Some(skip) = args.skip {
                if skip >= 0 {
                    let _ = file.seek(std::io::SeekFrom::Start(skip as u64));
                    // If seeking fails the bytes are skipped by reading.
                    if file.stream_position().map(|p| p == skip as u64).unwrap_or(false) {
                        start = skip as u64;
                    } else {
                        discard(&mut file, skip as u64)?;
                        start = skip as u64;
                    }
                } else {
                    file.seek(std::io::SeekFrom::End(skip))
                        .map_err(|_| anyhow!("Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe)."))?;
                }
            }
            Box::new(file)
        }
        None => {
            let mut stdin = std::io::stdin();
            if let Some(skip) = args.skip {
                if skip >= 0 {
                    discard(&mut stdin, skip as u64)?;
                    start = skip as u64;
                } else {
                    if stdin.seek(std::io::SeekFrom::End(skip)).is_err() {
                        bail!("Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).");
                    }
                }
            }
            Box::new(stdin)
        }
    };
    Ok((start, reader))
}

fn discard(reader: &mut dyn Read, mut count: u64) -> Result<()> {
    let mut buf = [0u8; 8192];
    while count > 0 {
        let want = count.min(buf.len() as u64) as usize;
        match reader.read(&mut buf[..want]) {
            Ok(0) => break,
            Ok(n) => count -= n as u64,
            Err(e) if e.kind() == std::io::ErrorKind::Interrupted => {}
            Err(e) => return Err(anyhow!("{e}")),
        }
    }
    Ok(())
}

fn print_include(args: &Args) -> Result<()> {
    let (_start, mut reader) = open_input(args)?;
    let mut data = Vec::new();
    match args.length {
        Some(n) => {
            data.reserve(n.max(0) as usize);
            let mut buf = vec![0u8; 65536];
            let mut left = n;
            while left > 0 {
                let want = left.min(buf.len() as i64) as usize;
                let got = read_full(&mut reader, &mut buf[..want])?;
                if got == 0 {
                    break;
                }
                data.extend_from_slice(&buf[..got]);
                left -= got as i64;
            }
        }
        None => {
            reader.read_to_end(&mut data)?;
        }
    }

    let mut out = String::new();
    if let Some(f) = &args.file {
        let path = std::path::Path::new(f);
        let mut name = String::new();
        if let Some(stem) = path.file_stem() {
            name.push_str(&sanitize(stem.to_string_lossy().as_ref()));
        }
        if let Some(ext) = path.extension() {
            if !ext.is_empty() {
                name.push('_');
                name.push_str(&sanitize(ext.to_string_lossy().as_ref()));
            }
        }
        out.push_str(&format!("unsigned char {}[] = {{\n", name));
        let mut lines: Vec<String> = Vec::new();
        let mut cur: Vec<String> = Vec::new();
        for b in &data {
            if cur.len() == 12 {
                lines.push(format!("  {},", cur.join(", ")));
                cur.clear();
            }
            cur.push(format!("0x{b:02x}"));
        }
        if data.is_empty() {
            lines.push(String::new());
        } else {
            lines.push(format!("  {}", cur.join(", ")));
        }
        for line in &lines {
            out.push_str(line);
            out.push('\n');
        }
        out.push_str("};\n");
        out.push_str(&format!("unsigned int {}_len = {};\n", name, data.len()));
    } else {
        let mut cur: Vec<String> = Vec::new();
        for b in &data {
            if cur.len() == 12 {
                out.push_str(&format!("  {},\n", cur.join(", ")));
                cur.clear();
            }
            cur.push(format!("0x{b:02x}"));
        }
        if !cur.is_empty() {
            out.push_str(&format!("  {}\n", cur.join(", ")));
        }
    }
    print!("{out}");
    Ok(())
}

fn sanitize(s: &str) -> String {
    s.chars()
        .map(|c| if c.is_ascii_alphanumeric() { c } else { '_' })
        .collect()
}

fn print_color_table() {
    let colors = Colors::new(Scheme::Default);
    let out = format!(
        "hexyl color reference:\n\n{}\u{22c4} NULL bytes (0x00)\n{RESET}\u{1b}[36ma ASCII printable characters (0x20 - 0x7E)\n{RESET}\u{1b}[32m_ ASCII whitespace (0x09 - 0x0D, 0x20)\n{RESET}\u{1b}[32m\u{2022} ASCII control characters (except NULL and whitespace)\n{RESET}\u{1b}[33m\u{d7} Non-ASCII bytes (0x80 - 0xFF)\n{RESET}",
        colors.offset.code
    );
    print!("{out}");
}
