/// Decides whether ANSI sequences should be emitted on the given stream.
pub fn should_colorize(is_terminal: bool) -> bool {
    if let Some(v) = std::env::var_os("CLICOLOR_FORCE") {
        let v = v.to_string_lossy().to_string();
        if !v.is_empty() && v != "0" {
            return true;
        }
    }
    if std::env::var_os("NO_COLOR").is_some() {
        return false;
    }
    if !is_terminal {
        return false;
    }
    if let Some(v) = std::env::var_os("CLICOLOR") {
        if v.to_string_lossy() == "0" {
            return false;
        }
    }
    match std::env::var("TERM") {
        Ok(t) => t != "dumb",
        Err(_) => false,
    }
}

/// Removes ANSI escape sequences from a string.
pub fn strip_ansi(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\x1b' {
            if let Some(&'[') = chars.peek() {
                chars.next();
                // Skip the parameters until the final byte of the sequence.
                let mut final_byte = false;
                for c in chars.by_ref() {
                    if c.is_ascii_alphabetic() {
                        final_byte = true;
                        break;
                    }
                }
                let _ = final_byte;
                continue;
            }
            continue;
        }
        out.push(c);
    }
    out
}

/// Writes a styled string to stdout, stripping colors when not appropriate.
pub fn print_styled(s: &str) {
    let is_tty = crate::render::stdout_is_terminal();
    if should_colorize(is_tty) {
        print!("{s}");
    } else {
        print!("{}", strip_ansi(s));
    }
}
