fn scan_flags(argv: &[OsString]) -> Vec<(usize, &'static str)> {
    let mut out = vec![];
    for (i, raw) in argv.iter().enumerate() {
        let a = raw.to_string_lossy();
        if a == "--" { break }
        if let Some(rest) = a.strip_prefix("--") {
            let name = rest.split('=').next().unwrap_or("");
            // map the name to a known flag
            match name {
                "characters" => out.push((i, "C")),
                "no-characters" => out.push((i, "no-characters")),
                "plain" => out.push((i, "p")),
                "no-position" => out.push((i, "no-position")),
                "border" => out.push((i, "border")),
                "color" => out.push((i, "color")),
                "length" | "bytes" | "skip" | "block-size" | "display-offset" | "panels" | "group-size" | "groupsize" | "endianness" | "base" | "terminal-width" | "completion" | "character-table" | "color-scheme" => { /* value-taking; if no '=', the value is the next arg */ }
                _ => {}
            }
        } else if a.len() > 1 && a.starts_with('-') {
            let chars: Vec<char> = a[1..].chars().collect();
            for (k, ch) in chars.iter().enumerate() {
                match ch {
                    'C' => out.push((i, "C")),
                    'p' => out.push((i, "p")),
                    'P' => out.push((i, "no-position")),
                    'v' => out.push((i, "no-squeezing")),
                    'h' | 'V' => out.push((i, "special")),
                    _ if short_values.contains(ch) => {
                        // takes a value: either the rest of the cluster or the next arg
                        break;
                    }
                    _ => {}
                }
            }
        }
    }
    out
}
